package com.supportsphere.util; import javafx.scene.control.*; public final class Dialogs {private Dialogs(){} public static void info(String h,String m){new Alert(Alert.AlertType.INFORMATION,h+"\n\n"+m,ButtonType.OK).showAndWait();} public static void error(String h,String m){new Alert(Alert.AlertType.ERROR,h+"\n\n"+m,ButtonType.OK).showAndWait();} public static boolean confirm(String h,String m){return new Alert(Alert.AlertType.CONFIRMATION,h+"\n\n"+m,ButtonType.YES,ButtonType.NO).showAndWait().orElse(ButtonType.NO)==ButtonType.YES;} public static String text(String h,String prompt){TextInputDialog d=new TextInputDialog();d.setTitle(h);d.setHeaderText(prompt);return d.showAndWait().orElse("");}}
